-- Zella Voice billing step 2: per-business plans, monthly balances, packs, rollover, buffer, usage counting, alerts.
-- Design: docs/ARCHITECTURE.md §17 (REQ-BIL-01, 11, 14-22, 55-57; D-41, D-42, D-43, D-46) and docs/PAYMENTS_ARCHITECTURE.md §4.
-- Safe to run twice. Rollback: sql/rollback/zella_billing_allowances_rollback.sql (generated by tests/setup/make_rollback.py billing).
-- Needs (all live): zella_settings_system, zella_call_usage, zella_billing_hardening, zella_plan_languages.
--
-- No money moves here. Nothing is charged, no provider is called and no plan, price or pack is bought. Pack prices are
-- the fixed list prices decided in §17.3. Packs can only be granted by a billing admin with a reason (an audited
-- adjustment, REQ-BIL-10); buying them with a payment comes with the payment integration (step 4, owner approval).
--
--   business_plans          each business's own plan, versioned; a change is a new version, never an edit (REQ-BIL-01, 57)
--   billing_pack_catalog    the fixed pack prices (§17.3)
--   billing_periods         one row per business per monthly allowance period (yearly plans too, D-46); the lock for usage
--   allowance_buckets       the current balances: rollover, plan, packs and the 5% buffer, per resource and period
--   pack_purchases          packs granted (and, from step 4, bought)
--   usage_charges           every subtraction from a balance, once per idempotency key (calls, texts, emails)
--   auto_reload_settings    the owner's auto-reload choice (stored only; reloads need payments, step 4)
--
-- What changes for existing logic (each patch checks the function is the version it was written against):
--   - subscriptions.plan_id may be empty: a business's plan is its business_plans version, not a shared plan
--   - plan limits (team seats, phone numbers, languages, minutes) come from the business's own plan when it has one
--   - minute allowance and alerts use the balances; alerts are at 80% and 100% (owner, 13 Nov 2026), for minutes,
--     texts and emails
--   - the shared plans table is readable only by billing admins and by members of a business on that plan
-- Not changed (needs the owner's approval to go live): calls are still not sent to the fallback number at 100%
-- (zella_call_entitlement_check reports it; nothing acts on it yet), texts and emails are not stopped at 100%
-- (zella_message_allowance reports it), and the 20-minute call cap (REQ-BIL-24) is the live setting
-- voice_max_call_seconds.

begin;

-- ---------------------------------------------------------------------------------------------------------------
-- 1. Settings (platform_settings, maintained by the Zella Voice owner; these are the defaults)
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.zella_billing_settings() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v jsonb := coalesce(public.zella_setting('billing_rules', '{}'::jsonb), '{}'::jsonb); r jsonb; k text;
begin
  if jsonb_typeof(v) <> 'object' then v := '{}'::jsonb; end if;
  r := jsonb_build_object(
    'rollover_percent', 20, 'buffer_percent', 5, 'alert_percents', jsonb_build_array(80, 100),
    'target_margin_percent', 60, 'max_minutes_warning', 10000, 'min_call_seconds', 15,
    'trial_days', 5, 'trial_minutes', 20, 'trial_texts', 5, 'trial_emails', 5) || (v - 'unit_costs' - 'alert_percents');
  foreach k in array array['rollover_percent', 'buffer_percent', 'target_margin_percent', 'max_minutes_warning', 'min_call_seconds',
                           'trial_days', 'trial_minutes', 'trial_texts', 'trial_emails'] loop
    if coalesce(jsonb_typeof(r -> k), '') <> 'number' or (r ->> k)::numeric < 0 or (r ->> k)::numeric > 1000000 then raise exception 'BAD_BILLING_RULES: %', k; end if;
  end loop;
  if (r ->> 'rollover_percent')::numeric > 100 or (r ->> 'buffer_percent')::numeric > 100 or (r ->> 'target_margin_percent')::numeric > 100 then
    raise exception 'BAD_BILLING_RULES: percent';
  end if;
  -- unit costs in US cents (sms_part, email, phone_number_month, texting_registration_month); unset = not known
  return r || jsonb_build_object('unit_costs', case when jsonb_typeof(v -> 'unit_costs') = 'object' then v -> 'unit_costs' else '{}'::jsonb end);
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 2. Tables
-- ---------------------------------------------------------------------------------------------------------------
create table if not exists public.business_plans (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  version integer not null check (version >= 1),
  tier text not null check (tier in ('base', 'pro')),
  billing_interval text not null check (billing_interval in ('monthly', 'yearly')),
  price_cents bigint not null check (price_cents >= 0),
  setup_fee_cents bigint not null default 0 check (setup_fee_cents >= 0),
  currency text not null default 'USD' check (currency = 'USD'),
  minutes integer not null check (minutes between 0 and 1000000),
  texts integer not null check (texts between 0 and 10000000),
  emails integer not null check (emails between 0 and 100000000),
  team_seats integer not null check (team_seats between 1 and 1000),
  phone_numbers integer not null check (phone_numbers between 1 and 100),
  locations integer not null check (locations between 1 and 100),
  languages text[] not null check (cardinality(languages) between 1 and 2 and languages <@ array['en', 'es']),
  trial_enabled boolean not null default false,
  -- pay as you go (D-44): the price of each minute past the allowance when the owner chooses it; empty = not offered
  overage_cents_per_minute integer check (overage_cents_per_minute between 1 and 1000),
  contact_limits jsonb not null default '{}' check (jsonb_typeof(contact_limits) = 'object'),
  estimate jsonb not null default '{}',
  acknowledged_warnings jsonb not null default '[]',
  effective_from timestamptz not null default now(),
  idempotency_key text not null check (length(idempotency_key) between 8 and 100),
  values_hash text not null,
  created_by uuid,
  created_at timestamptz not null default now(),
  unique (business_id, version),
  unique (business_id, idempotency_key)
);
create index if not exists business_plans_current_idx on public.business_plans (business_id, version desc);

create table if not exists public.billing_pack_catalog (
  code text primary key check (code ~ '^[a-z]+_[0-9]+$'),
  resource text not null check (resource in ('minutes', 'texts', 'emails')),
  quantity integer not null check (quantity > 0),
  price_cents bigint not null check (price_cents > 0),
  currency text not null default 'USD' check (currency = 'USD'),
  active boolean not null default true,
  unique (resource, quantity)
);

create table if not exists public.billing_periods (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  subscription_id uuid references public.subscriptions (id) on delete set null,
  business_plan_id uuid not null references public.business_plans (id),
  period_start timestamptz not null,
  period_end timestamptz not null check (period_end > period_start),
  is_trial boolean not null default false,
  created_at timestamptz not null default now(),
  unique (business_id, period_start)
);
create index if not exists billing_periods_end_idx on public.billing_periods (business_id, period_end);

create table if not exists public.pack_purchases (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  pack_code text not null references public.billing_pack_catalog (code),
  resource text not null check (resource in ('minutes', 'texts', 'emails')),
  quantity integer not null check (quantity > 0),
  price_cents bigint not null check (price_cents >= 0),
  currency text not null default 'USD' check (currency = 'USD'),
  -- step 2 has only admin grants (no charge); 'paid' and 'refunded' arrive with payments (step 4)
  status text not null check (status in ('granted')),
  source text not null check (source in ('admin_grant')),
  reason text not null check (length(trim(reason)) >= 5),
  period_id uuid not null references public.billing_periods (id),
  idempotency_key text not null check (length(idempotency_key) between 8 and 100),
  created_by uuid,
  purchased_at timestamptz not null default now(),
  unique (business_id, idempotency_key)
);

create table if not exists public.allowance_buckets (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  period_id uuid not null references public.billing_periods (id) on delete cascade,
  resource text not null check (resource in ('minutes', 'texts', 'emails')),
  kind text not null check (kind in ('rollover', 'plan', 'pack', 'buffer')),
  pack_purchase_id uuid references public.pack_purchases (id),
  granted numeric(14, 4) not null check (granted > 0),
  used numeric(14, 4) not null default 0,
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  check (used >= 0 and used <= granted),
  check (case kind when 'pack' then pack_purchase_id is not null when 'rollover' then true else pack_purchase_id is null end),
  check (kind <> 'buffer' or resource in ('texts', 'emails'))
);
create unique index if not exists allowance_buckets_once_idx
  on public.allowance_buckets (period_id, resource, kind, coalesce(pack_purchase_id, '00000000-0000-0000-0000-000000000000'::uuid));
create index if not exists allowance_buckets_business_idx on public.allowance_buckets (business_id, resource, expires_at);

create table if not exists public.usage_charges (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  period_id uuid not null references public.billing_periods (id),
  resource text not null check (resource in ('minutes', 'texts', 'emails')),
  idempotency_key text not null unique check (length(idempotency_key) between 8 and 200),
  quantity numeric(14, 4) not null,                   -- negative: given back (a shorter call, a call later marked spam)
  allocations jsonb not null default '[]',            -- [{bucket_id, kind, quantity}]
  over_quantity numeric(14, 4) not null default 0,    -- what no balance covered (a call in progress is never cut)
  source_kind text not null check (source_kind in ('call', 'sms', 'email', 'admin')),
  source_id uuid,
  message_kind text check (message_kind in ('appointment', 'routine')),
  occurred_at timestamptz not null,
  created_at timestamptz not null default now()
);
create index if not exists usage_charges_source_idx on public.usage_charges (source_kind, source_id);
create index if not exists usage_charges_period_idx on public.usage_charges (period_id, resource);

create table if not exists public.auto_reload_settings (
  business_id uuid not null references public.businesses (id) on delete cascade,
  resource text not null check (resource in ('minutes', 'texts', 'emails')),
  enabled boolean not null default false,
  threshold integer not null check (threshold >= 0),
  pack_code text not null references public.billing_pack_catalog (code),
  monthly_cap_cents bigint not null check (monthly_cap_cents > 0),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  primary key (business_id, resource)
);

-- deny by default: no table grants; owners and billing admins read through the functions below
do $$ declare t text; begin
  foreach t in array array['business_plans', 'billing_pack_catalog', 'billing_periods', 'pack_purchases', 'allowance_buckets',
                           'usage_charges', 'auto_reload_settings'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
end $$;

-- a plan version and a usage charge are history: never edited or removed (a business's deletion cascades)
create or replace function public.zella_billing_immutable_trg() returns trigger
language plpgsql set search_path = public as $$
begin
  raise exception 'IMMUTABLE: % rows are never changed', tg_table_name;
end $$;
drop trigger if exists zella_business_plans_immutable on public.business_plans;
create trigger zella_business_plans_immutable before update on public.business_plans for each row execute function public.zella_billing_immutable_trg();
drop trigger if exists zella_usage_charges_immutable on public.usage_charges;
create trigger zella_usage_charges_immutable before update on public.usage_charges for each row execute function public.zella_billing_immutable_trg();

-- fixed pack prices (§17.3, D-41)
insert into public.billing_pack_catalog (code, resource, quantity, price_cents) values
  ('minutes_100', 'minutes', 100, 2900), ('minutes_250', 'minutes', 250, 8900), ('minutes_500', 'minutes', 500, 14900),
  ('minutes_1000', 'minutes', 1000, 26900),
  ('texts_500', 'texts', 500, 1800), ('texts_1000', 'texts', 1000, 3400), ('texts_2500', 'texts', 2500, 8000), ('texts_5000', 'texts', 5000, 15000),
  ('emails_10000', 'emails', 10000, 2500), ('emails_25000', 'emails', 25000, 5900), ('emails_50000', 'emails', 50000, 11500)
on conflict (code) do nothing;

-- a charge that could not be recorded is listed (and retried) like other usage problems
alter table public.usage_processing_issues drop constraint if exists usage_processing_issues_kind_check;
alter table public.usage_processing_issues add constraint usage_processing_issues_kind_check
  check (kind = any (array['missing_duration', 'invalid_duration', 'processing_failed', 'duration_changed', 'summary_mismatch', 'billing_charge_failed']));

-- the alerts table also measures texts and emails now (its *_minutes columns hold the count for those)
alter table public.usage_threshold_events add column if not exists resource text not null default 'minutes';

-- ---------------------------------------------------------------------------------------------------------------
-- 3. Plans: evaluate (margin, limits), save as a new version (billing admins), current plan, limits
-- ---------------------------------------------------------------------------------------------------------------
-- REQ-BIL-55/56: one calculation for the plan page, the review screen and the audit record. Errors block; warnings
-- need a written reason. Unit costs that are not set are reported, never guessed.
create or replace function public.zella_plan_evaluate(p_values jsonb) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare s jsonb := public.zella_billing_settings(); c jsonb; e text[] := '{}'; w jsonb := '[]'; v jsonb := '{}'; k text;
        v_voice numeric; v_cost numeric := 0; v_rev numeric; v_margin numeric; v_missing text[] := '{}'; v_lang jsonb;
begin
  -- the estimate reveals Zella Voice's unit costs: billing admins only (no signed-in user = the server)
  -- (billing.manage implies it: zella_admin_plan_save, which needs billing.manage, calls this)
  if auth.uid() is not null and not (public.zella_admin_can('billing.view') or public.zella_admin_can('billing.manage')) then raise exception 'NOT_ALLOWED'; end if;
  if p_values is null or jsonb_typeof(p_values) <> 'object' then return jsonb_build_object('ok', false, 'errors', jsonb_build_array('values')); end if;
  c := s -> 'unit_costs';
  v := jsonb_build_object('tier', p_values ->> 'tier', 'billing_interval', p_values ->> 'billing_interval',
                          'trial_enabled', coalesce(p_values -> 'trial_enabled', 'false'::jsonb));
  if coalesce(p_values ->> 'tier', '') not in ('base', 'pro') then e := e || 'tier'::text; end if;
  if coalesce(p_values ->> 'billing_interval', '') not in ('monthly', 'yearly') then e := e || 'billing_interval'::text; end if;
  if coalesce(jsonb_typeof(v -> 'trial_enabled'), '') <> 'boolean' then e := e || 'trial_enabled'::text; end if;
  foreach k in array array['price_cents', 'setup_fee_cents', 'minutes', 'texts', 'emails', 'team_seats', 'phone_numbers', 'locations'] loop
    if coalesce(jsonb_typeof(p_values -> k), '') <> 'number' or coalesce(p_values ->> k, '') !~ '^[0-9]{1,12}$'
       or (k in ('team_seats', 'phone_numbers', 'locations') and (p_values ->> k)::bigint < 1)
       or (k = 'minutes' and (p_values ->> k)::bigint > 1000000) or (k = 'texts' and (p_values ->> k)::bigint > 10000000)
       or (k = 'emails' and (p_values ->> k)::bigint > 100000000) or (k = 'team_seats' and (p_values ->> k)::bigint > 1000)
       or (k in ('phone_numbers', 'locations') and (p_values ->> k)::bigint > 100) then
      e := e || k;
    else
      v := v || jsonb_build_object(k, (p_values ->> k)::bigint);
    end if;
  end loop;
  v_lang := p_values -> 'languages';
  if coalesce(jsonb_typeof(v_lang), '') <> 'array' or jsonb_array_length(v_lang) not between 1 and 2
     or exists (select 1 from jsonb_array_elements(v_lang) x where jsonb_typeof(x) <> 'string' or x #>> '{}' not in ('en', 'es'))
     or (select count(distinct x #>> '{}') from jsonb_array_elements(v_lang) x) <> jsonb_array_length(v_lang) then
    e := e || 'languages'::text;
  else
    v := v || jsonb_build_object('languages', v_lang);
  end if;
  if p_values ? 'contact_limits' and jsonb_typeof(p_values -> 'contact_limits') <> 'object' then e := e || 'contact_limits'::text; end if;
  -- pay-as-you-go rate per extra minute, in cents (D-44): optional; empty means the business can't choose pay as you go
  if coalesce(jsonb_typeof(p_values -> 'overage_cents_per_minute'), 'null') = 'null' then
    v := v || jsonb_build_object('overage_cents_per_minute', null);
  elsif jsonb_typeof(p_values -> 'overage_cents_per_minute') <> 'number' or (p_values ->> 'overage_cents_per_minute') !~ '^[0-9]{1,4}$'
        or (p_values ->> 'overage_cents_per_minute')::int not between 1 and 1000 then
    e := e || 'overage_cents_per_minute'::text;
  else
    v := v || jsonb_build_object('overage_cents_per_minute', (p_values ->> 'overage_cents_per_minute')::int);
  end if;
  v := v || jsonb_build_object('contact_limits', coalesce(case when jsonb_typeof(p_values -> 'contact_limits') = 'object' then p_values -> 'contact_limits' end, '{}'::jsonb));
  if cardinality(e) > 0 then return jsonb_build_object('ok', false, 'errors', to_jsonb(e), 'values', v); end if;

  -- estimated monthly cost (US cents): minutes at today's voice rates, texts as one part each, emails, numbers, registration
  select sum(x.unit_cost) * 100 into v_voice from (
    select distinct on (provider) unit_cost from public.voice_pricing where component = 'per_minute' and currency = 'USD' and effective_from <= now()
     order by provider, effective_from desc) x;
  if v_voice is null then v_missing := v_missing || 'voice_minute'::text; else v_cost := v_cost + v_voice * (v ->> 'minutes')::numeric; end if;
  foreach k in array array['sms_part', 'email', 'phone_number_month', 'texting_registration_month'] loop
    if coalesce(jsonb_typeof(c -> k), '') <> 'number' or (c ->> k)::numeric < 0 then v_missing := v_missing || k; end if;
  end loop;
  v_cost := v_cost
    + coalesce((c ->> 'sms_part')::numeric * (v ->> 'texts')::numeric, 0) * (jsonb_typeof(c -> 'sms_part') = 'number')::int
    + coalesce((c ->> 'email')::numeric * (v ->> 'emails')::numeric, 0) * (jsonb_typeof(c -> 'email') = 'number')::int
    + coalesce((c ->> 'phone_number_month')::numeric * (v ->> 'phone_numbers')::numeric, 0) * (jsonb_typeof(c -> 'phone_number_month') = 'number')::int
    + coalesce((c ->> 'texting_registration_month')::numeric * (v ->> 'locations')::numeric, 0) * (jsonb_typeof(c -> 'texting_registration_month') = 'number')::int;
  v_rev := case when v ->> 'billing_interval' = 'yearly' then (v ->> 'price_cents')::numeric / 12 else (v ->> 'price_cents')::numeric end;
  v_margin := case when v_rev > 0 then round((v_rev - v_cost) * 100 / v_rev, 1) end;

  if cardinality(v_missing) > 0 then
    w := w || jsonb_build_object('code', 'costs_not_configured', 'level', 'caution', 'detail', to_jsonb(v_missing));
  end if;
  if (v ->> 'price_cents')::bigint = 0 then w := w || jsonb_build_object('code', 'price_zero', 'level', 'red'); end if;
  if v_margin is not null and v_margin < 0 then w := w || jsonb_build_object('code', 'loss', 'level', 'red', 'margin_percent', v_margin);
  elsif v_margin is not null and v_margin < (s ->> 'target_margin_percent')::numeric then
    w := w || jsonb_build_object('code', 'below_target_margin', 'level', 'caution', 'margin_percent', v_margin, 'target', (s ->> 'target_margin_percent')::numeric);
  end if;
  if v_voice is not null and (v ->> 'overage_cents_per_minute') is not null and (v ->> 'overage_cents_per_minute')::numeric < v_voice then
    w := w || jsonb_build_object('code', 'overage_below_cost', 'level', 'red', 'cost_cents', round(v_voice, 2));
  end if;
  if (v ->> 'minutes')::numeric > (s ->> 'max_minutes_warning')::numeric then
    w := w || jsonb_build_object('code', 'minutes_high', 'level', 'red', 'limit', (s ->> 'max_minutes_warning')::numeric);
  end if;
  return jsonb_build_object('ok', true, 'errors', '[]'::jsonb, 'values', v, 'warnings', w,
    'estimate', jsonb_build_object('monthly_cost_cents', round(v_cost), 'monthly_revenue_cents', round(v_rev), 'margin_percent', v_margin,
                                   'setup_fee_cents', (v ->> 'setup_fee_cents')::bigint, 'costs_complete', cardinality(v_missing) = 0));
end $$;

-- REQ-BIL-57: confirming the review saves a new version and an audit record. Only billing admins (billing.manage).
-- p_acknowledgements: {"<warning code>": "<reason>"} for every warning. The same key with the same values returns the
-- saved version; the same key with different values is refused.
create or replace function public.zella_admin_plan_save(p_business_id uuid, p_values jsonb, p_acknowledgements jsonb, p_idempotency_key text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare r jsonb; v jsonb; w jsonb; x jsonb; v_hash text; prev public.business_plans; v_new public.business_plans; acks jsonb := '[]';
begin
  if auth.uid() is null or not public.zella_admin_can('billing.manage') then raise exception 'NOT_ALLOWED'; end if;
  if p_idempotency_key is null or length(p_idempotency_key) not between 8 and 100 then raise exception 'BAD_IDEMPOTENCY_KEY'; end if;
  if not exists (select 1 from public.businesses where id = p_business_id) then raise exception 'NOT_FOUND'; end if;
  perform pg_advisory_xact_lock(hashtextextended('zella_business_plan:' || p_business_id::text, 0));
  r := public.zella_plan_evaluate(p_values);
  if not (r ->> 'ok')::boolean then raise exception 'INVALID_PLAN' using detail = (r -> 'errors')::text; end if;
  v := r -> 'values'; w := r -> 'warnings';
  v_hash := md5(v::text);
  select * into prev from public.business_plans where business_id = p_business_id and idempotency_key = p_idempotency_key;
  if prev.id is not null then
    if prev.values_hash <> v_hash then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
    return jsonb_build_object('result', 'duplicate', 'plan_id', prev.id, 'version', prev.version);
  end if;
  for x in select * from jsonb_array_elements(w) loop
    if coalesce(jsonb_typeof(p_acknowledgements -> (x ->> 'code')), '') <> 'string' or coalesce(length(trim(p_acknowledgements ->> (x ->> 'code'))), 0) < 5 then
      raise exception 'WARNING_NOT_ACKNOWLEDGED' using detail = x ->> 'code';
    end if;
    acks := acks || (x || jsonb_build_object('reason', left(trim(p_acknowledgements ->> (x ->> 'code')), 500)));
  end loop;
  insert into public.business_plans (business_id, version, tier, billing_interval, price_cents, setup_fee_cents, minutes, texts, emails,
      team_seats, phone_numbers, locations, languages, trial_enabled, overage_cents_per_minute, contact_limits, estimate, acknowledged_warnings, idempotency_key,
      values_hash, created_by)
  values (p_business_id, coalesce((select max(version) from public.business_plans where business_id = p_business_id), 0) + 1,
      v ->> 'tier', v ->> 'billing_interval', (v ->> 'price_cents')::bigint, (v ->> 'setup_fee_cents')::bigint, (v ->> 'minutes')::int,
      (v ->> 'texts')::int, (v ->> 'emails')::int, (v ->> 'team_seats')::int, (v ->> 'phone_numbers')::int, (v ->> 'locations')::int,
      array(select jsonb_array_elements_text(v -> 'languages')), (v ->> 'trial_enabled')::boolean, (v ->> 'overage_cents_per_minute')::int, v -> 'contact_limits', r -> 'estimate',
      acks, p_idempotency_key, v_hash, auth.uid())
  returning * into v_new;
  insert into public.audit_logs (business_id, user_id, action, entity_type, entity_id, old_data, new_data)
  values (p_business_id, auth.uid(), 'billing.plan_saved', 'business_plan', v_new.id,
          case when v_new.version > 1 then (select to_jsonb(b) - 'values_hash' from public.business_plans b where b.business_id = p_business_id and b.version = v_new.version - 1) end,
          jsonb_build_object('version', v_new.version, 'values', v, 'estimate', r -> 'estimate', 'acknowledged_warnings', acks));
  return jsonb_build_object('result', 'saved', 'plan_id', v_new.id, 'version', v_new.version, 'estimate', r -> 'estimate', 'acknowledged_warnings', acks);
end $$;

create or replace function public.zella_billing_plan_current(p_business_id uuid) returns public.business_plans
language sql stable security definer set search_path = public as $$
  select * from public.business_plans where business_id = p_business_id order by version desc limit 1;
$$;

-- the plan version a period uses: the latest saved before it started (changes apply from the next period; mid-period
-- upgrades with a prorated charge come with payments, REQ-BIL-30), or the first version when none is older
create or replace function public.zella_billing_plan_at(p_business_id uuid, p_at timestamptz) returns public.business_plans
language sql stable security definer set search_path = public as $$
  select * from public.business_plans where business_id = p_business_id
   order by (effective_from <= p_at) desc, case when effective_from <= p_at then version else -version end desc limit 1;
$$;

-- the limits existing checks read (team_members, phone_numbers, languages, voice_minutes ...): the business's own plan
-- when it has one, otherwise the shared plan's limits
create or replace function public.zella_plan_limits(p_business_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare b public.business_plans; s public.subscriptions; l jsonb; bnd jsonb;
begin
  -- the plan in effect: the version the current period started with (a downgrade applies from the next billing date);
  -- before the first period, the latest saved version
  bnd := public.zella_billing_period_bounds(p_business_id, now());
  b := case when bnd is not null then public.zella_billing_plan_at(p_business_id, (bnd ->> 'from')::timestamptz) else public.zella_billing_plan_current(p_business_id) end;
  if b.id is not null then
    return b.contact_limits || jsonb_build_object('voice_minutes', b.minutes, 'texts', b.texts, 'emails', b.emails, 'team_members', b.team_seats,
      'phone_numbers', b.phone_numbers, 'locations', b.locations, 'languages', cardinality(b.languages));
  end if;
  s := public.zella_current_subscription(p_business_id);
  select p.limits into l from public.plans p where p.id = s.plan_id;
  return coalesce(l, '{}'::jsonb);
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 4. Periods and balances
-- ---------------------------------------------------------------------------------------------------------------
-- The allowance period containing p_at: the trial, or the paid period (monthly), or the month of a yearly period on the
-- same day each month (D-46; anchor + n months, so the 31st falls on the last day of shorter months). None when the
-- subscription is not current or the paid period has not started (a monthly refresh happens once the charge succeeds).
create or replace function public.zella_billing_period_bounds(p_business_id uuid, p_at timestamptz) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare s public.subscriptions; b public.business_plans; k integer := 0; v_from timestamptz; v_to timestamptz;
begin
  s := public.zella_current_subscription(p_business_id);
  if s.id is null then return null; end if;
  if s.status = 'trial' then
    if s.trial_start_at is null or s.trial_end_at is null or p_at < s.trial_start_at or p_at >= s.trial_end_at then return null; end if;
    return jsonb_build_object('from', s.trial_start_at, 'to', s.trial_end_at, 'trial', true, 'subscription_id', s.id);
  end if;
  if s.current_period_start is null or s.current_period_end is null or p_at < s.current_period_start or p_at >= s.current_period_end then return null; end if;
  b := public.zella_billing_plan_at(p_business_id, s.current_period_start);
  if coalesce(b.billing_interval, s.billing_interval) <> 'yearly' then
    return jsonb_build_object('from', s.current_period_start, 'to', s.current_period_end, 'trial', false, 'subscription_id', s.id);
  end if;
  while k < 12 and s.current_period_start + make_interval(months => k + 1) <= p_at loop k := k + 1; end loop;
  v_from := s.current_period_start + make_interval(months => k);
  v_to := least(s.current_period_start + make_interval(months => k + 1), s.current_period_end);
  return jsonb_build_object('from', v_from, 'to', v_to, 'trial', false, 'subscription_id', s.id);
end $$;

-- Opens (once) the period containing p_at and grants its balances; returns the period locked for update, so every
-- change to one business's balances is serialised. Rollover (REQ-BIL-19/20): from the period that ended exactly when
-- this one starts, up to 20% of the plan's minutes and up to 20% of each minutes pack, for one period; texts and emails
-- don't roll over. Buffer (REQ-BIL-22): 5% of the plan's texts and emails, appointment messages only. Trial (REQ-BIL-11):
-- 20 minutes, 5 texts, 5 emails, no rollover, no buffer.
create or replace function public.zella_billing_open_period(p_business_id uuid, p_at timestamptz) returns public.billing_periods
language plpgsql security definer set search_path = public as $$
declare bnd jsonb; pbnd jsonb; s jsonb := public.zella_billing_settings(); p public.billing_periods; b public.business_plans; prev public.billing_periods;
        r text; q numeric; x record; pb public.business_plans; v_from timestamptz;
begin
  if p_business_id is null or p_at is null then return null; end if;
  bnd := public.zella_billing_period_bounds(p_business_id, p_at);
  if bnd is null then
    -- not the current paid or trial window: an event that happened in an earlier period is counted in that period
    -- (for example a call that ended just before the monthly charge and was processed after it)
    select * into p from public.billing_periods where business_id = p_business_id and period_start <= p_at and p_at < period_end
     order by period_start desc limit 1 for update;
    return p;
  end if;
  v_from := (bnd ->> 'from')::timestamptz;
  select * into p from public.billing_periods where business_id = p_business_id and period_start = v_from for update;
  if p.id is not null then return p; end if;
  b := public.zella_billing_plan_at(p_business_id, v_from);
  if b.id is null then return null; end if;
  -- locks always go from the earlier period to the later one (here and in zella_usage_consume), so they never deadlock.
  -- The previous month is opened first when it was part of the same paid year but nothing happened in it, so its
  -- unused minutes still roll over; a gap between subscriptions has no previous window and gives no rollover.
  if not (bnd ->> 'trial')::boolean then
    select * into prev from public.billing_periods where business_id = p_business_id and period_end = v_from and not is_trial
     order by period_start desc limit 1 for update;
    if prev.id is null then
      pbnd := public.zella_billing_period_bounds(p_business_id, v_from - interval '1 microsecond');
      if pbnd is not null and (pbnd ->> 'to')::timestamptz = v_from and not (pbnd ->> 'trial')::boolean then
        prev := public.zella_billing_open_period(p_business_id, v_from - interval '1 microsecond');
      end if;
    end if;
  end if;
  insert into public.billing_periods (business_id, subscription_id, business_plan_id, period_start, period_end, is_trial)
  values (p_business_id, (bnd ->> 'subscription_id')::uuid, b.id, v_from, (bnd ->> 'to')::timestamptz, (bnd ->> 'trial')::boolean)
  on conflict (business_id, period_start) do nothing returning * into p;
  if p.id is null then
    select * into p from public.billing_periods where business_id = p_business_id and period_start = v_from for update;
    return p;
  end if;
  -- new period: grant its balances (only the transaction that created it gets here)
  foreach r in array array['minutes', 'texts', 'emails'] loop
    q := case when p.is_trial then (s ->> ('trial_' || r))::numeric
              else case r when 'minutes' then b.minutes when 'texts' then b.texts else b.emails end end;
    if q > 0 then
      insert into public.allowance_buckets (business_id, period_id, resource, kind, granted, expires_at) values (p_business_id, p.id, r, 'plan', q, p.period_end);
    end if;
    if not p.is_trial and r <> 'minutes' and floor(q * (s ->> 'buffer_percent')::numeric / 100) > 0 then
      insert into public.allowance_buckets (business_id, period_id, resource, kind, granted, expires_at)
      values (p_business_id, p.id, r, 'buffer', floor(q * (s ->> 'buffer_percent')::numeric / 100), p.period_end);
    end if;
  end loop;
  if not p.is_trial and prev.id is not null then
    select * into pb from public.business_plans where id = prev.business_plan_id;
    for x in
      select k.kind, k.pack_purchase_id, k.granted - k.used as unused,
             floor(case when k.kind = 'plan' then pb.minutes else pp.quantity end * (s ->> 'rollover_percent')::numeric / 100) as cap
        from public.allowance_buckets k left join public.pack_purchases pp on pp.id = k.pack_purchase_id
       where k.period_id = prev.id and k.resource = 'minutes' and k.kind in ('plan', 'pack')
    loop
      if least(x.unused, x.cap) > 0 then
        insert into public.allowance_buckets (business_id, period_id, resource, kind, pack_purchase_id, granted, expires_at)
        values (p_business_id, p.id, 'minutes', 'rollover', x.pack_purchase_id, least(x.unused, x.cap), p.period_end);
      end if;
    end loop;
  end if;
  return p;
end $$;

-- the next period's rollover follows what is really unused in the earlier one, both ways: late usage there lowers it
-- (never below what was already used from it), a give-back there raises it again (up to the 20% cap), and a rollover
-- bucket that went to zero comes back. Called with the earlier period locked; locks the next one (earlier before
-- later, as everywhere).
create or replace function public.zella_billing_rollover_reconcile(p_period_id uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare p public.billing_periods; n public.billing_periods; pb public.business_plans; s jsonb := public.zella_billing_settings(); x record; v_new numeric; c integer := 0;
begin
  select * into p from public.billing_periods where id = p_period_id;
  if p.id is null or p.is_trial then return 0; end if;
  select * into n from public.billing_periods where business_id = p.business_id and period_start = p.period_end and not is_trial for update;
  if n.id is null then return 0; end if;
  select * into pb from public.business_plans where id = p.business_plan_id;
  for x in
    select k.pack_purchase_id, rb.id as rid, rb.granted, rb.used,
           greatest(0, least(k.granted - k.used, floor(case when k.kind = 'plan' then pb.minutes else pp.quantity end * (s ->> 'rollover_percent')::numeric / 100))) as should
      from public.allowance_buckets k
      left join public.pack_purchases pp on pp.id = k.pack_purchase_id
      left join public.allowance_buckets rb on rb.period_id = n.id and rb.resource = 'minutes' and rb.kind = 'rollover'
           and rb.pack_purchase_id is not distinct from k.pack_purchase_id
     where k.period_id = p.id and k.resource = 'minutes' and k.kind in ('plan', 'pack')
     for update of k
  loop
    if x.rid is null then
      continue when x.should <= 0;
      insert into public.allowance_buckets (business_id, period_id, resource, kind, pack_purchase_id, granted, expires_at)
      values (p.business_id, n.id, 'minutes', 'rollover', x.pack_purchase_id, x.should, n.period_end);
      c := c + 1;
      continue;
    end if;
    v_new := greatest(x.should, x.used);
    continue when v_new = x.granted;
    if v_new <= 0 then delete from public.allowance_buckets where id = x.rid;
    else update public.allowance_buckets set granted = v_new where id = x.rid; end if;
    c := c + 1;
  end loop;
  return c;
end $$;

-- the order balances are used in (REQ-BIL-18): rolled over (the plan's first, then packs oldest first), plan, packs
-- oldest first, and the buffer last, for appointment messages only
create or replace function public.zella_billing_bucket_rank(p_kind text, p_has_pack boolean) returns integer
language sql immutable set search_path = public as $$
  select case p_kind when 'rollover' then case when p_has_pack then 1 else 0 end when 'plan' then 2 when 'pack' then 3 else 4 end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- 5. Usage: subtract once per key, give back once per key (server only)
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.zella_usage_consume(p_business_id uuid, p_resource text, p_quantity numeric, p_key text,
    p_source_kind text, p_source_id uuid, p_message_kind text default null, p_at timestamptz default now())
returns jsonb language plpgsql security definer set search_path = public as $$
declare p public.billing_periods; v_left numeric; v_take numeric; k record; v_alloc jsonb := '[]'; v_id uuid; v_old public.usage_charges;
begin
  if p_resource not in ('minutes', 'texts', 'emails') or p_quantity is null or p_quantity <= 0 or p_quantity > 100000 then raise exception 'BAD_INPUT'; end if;
  if p_key is null or length(p_key) not between 8 and 200 then raise exception 'BAD_IDEMPOTENCY_KEY'; end if;
  if p_resource <> 'minutes' and coalesce(p_message_kind, '') not in ('appointment', 'routine') then raise exception 'BAD_INPUT'; end if;
  select * into v_old from public.usage_charges where idempotency_key = p_key;
  if v_old.id is not null then return jsonb_build_object('result', 'duplicate', 'charge_id', v_old.id); end if;
  p := public.zella_billing_open_period(p_business_id, coalesce(p_at, now()));
  if p.id is null then return jsonb_build_object('result', 'not_configured'); end if;
  -- checked again under the period lock: a concurrent duplicate waited for it
  select * into v_old from public.usage_charges where idempotency_key = p_key;
  if v_old.id is not null then return jsonb_build_object('result', 'duplicate', 'charge_id', v_old.id); end if;
  v_left := p_quantity;
  for k in
    select b.id, b.kind, b.granted - b.used as free from public.allowance_buckets b left join public.pack_purchases pp on pp.id = b.pack_purchase_id
     where b.period_id = p.id and b.resource = p_resource and b.used < b.granted
       and (b.kind <> 'buffer' or p_message_kind = 'appointment')
     order by public.zella_billing_bucket_rank(b.kind, b.pack_purchase_id is not null), pp.purchased_at nulls first, b.created_at, b.id
     for update of b
  loop
    exit when v_left <= 0;
    v_take := least(v_left, k.free);
    update public.allowance_buckets set used = used + v_take where id = k.id;
    v_alloc := v_alloc || jsonb_build_object('bucket_id', k.id, 'kind', k.kind, 'quantity', v_take);
    v_left := v_left - v_take;
  end loop;
  insert into public.usage_charges (business_id, period_id, resource, idempotency_key, quantity, allocations, over_quantity, source_kind, source_id,
      message_kind, occurred_at)
  values (p_business_id, p.id, p_resource, p_key, p_quantity, v_alloc, v_left, p_source_kind, p_source_id, p_message_kind, coalesce(p_at, now()))
  returning id into v_id;
  -- usage recorded late in an earlier period: the next period's rollover can't count those minutes as unused
  if p_resource = 'minutes' and p.period_end <= now() then perform public.zella_billing_rollover_reconcile(p.id); end if;
  return jsonb_build_object('result', 'recorded', 'charge_id', v_id, 'period_id', p.id, 'allocations', v_alloc, 'over', v_left);
end $$;

-- gives back up to p_quantity of what earlier charges for this source took: what no balance covered first, then the
-- buckets in reverse order of use. A give-back to an earlier period restores that period's balance and so the next
-- period's rollover (zella_billing_rollover_reconcile).
create or replace function public.zella_usage_release(p_business_id uuid, p_resource text, p_quantity numeric, p_key text,
    p_source_kind text, p_source_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_old public.usage_charges; c record; a record; v_left numeric; v_back numeric; v_over numeric; v_alloc jsonb := '[]'; v_id uuid; v_period uuid;
begin
  if p_quantity is null or p_quantity <= 0 or p_key is null or length(p_key) not between 8 and 200 then raise exception 'BAD_INPUT'; end if;
  select * into v_old from public.usage_charges where idempotency_key = p_key;
  if v_old.id is not null then return jsonb_build_object('result', 'duplicate', 'charge_id', v_old.id); end if;
  select period_id into v_period from public.usage_charges where source_kind = p_source_kind and source_id = p_source_id and resource = p_resource
   order by created_at limit 1;
  if v_period is null then return jsonb_build_object('result', 'nothing_charged'); end if;
  perform 1 from public.billing_periods where id = v_period for update;
  select * into v_old from public.usage_charges where idempotency_key = p_key;
  if v_old.id is not null then return jsonb_build_object('result', 'duplicate', 'charge_id', v_old.id); end if;
  v_left := p_quantity;
  -- what no balance covered is given back first
  select coalesce(sum(over_quantity), 0) into v_over from public.usage_charges where source_kind = p_source_kind and source_id = p_source_id and resource = p_resource;
  v_back := least(v_left, greatest(v_over, 0)); v_left := v_left - v_back; v_over := -v_back;
  for a in
    select (e ->> 'bucket_id')::uuid as bucket_id, e ->> 'kind' as kind, sum((e ->> 'quantity')::numeric) as qty, max(u.created_at) as at
      from public.usage_charges u, jsonb_array_elements(u.allocations) e
     where u.source_kind = p_source_kind and u.source_id = p_source_id and u.resource = p_resource
     group by 1, 2 having sum((e ->> 'quantity')::numeric) > 0
     order by public.zella_billing_bucket_rank(e ->> 'kind', false) desc, max(u.created_at) desc
  loop
    exit when v_left <= 0;
    select b.id, least(v_left, a.qty, b.used) as back into c from public.allowance_buckets b
     where b.id = a.bucket_id for update;
    continue when c.id is null or c.back <= 0;
    update public.allowance_buckets set used = used - c.back where id = c.id;
    v_alloc := v_alloc || jsonb_build_object('bucket_id', c.id, 'kind', a.kind, 'quantity', -c.back);
    v_left := v_left - c.back;
  end loop;
  insert into public.usage_charges (business_id, period_id, resource, idempotency_key, quantity, allocations, over_quantity, source_kind, source_id, occurred_at)
  values (p_business_id, v_period, p_resource, p_key, -p_quantity, v_alloc, v_over, p_source_kind, p_source_id, now())
  returning id into v_id;
  if p_resource = 'minutes' and (select period_end from public.billing_periods where id = v_period) <= now() then
    perform public.zella_billing_rollover_reconcile(v_period);
  end if;
  return jsonb_build_object('result', 'released', 'charge_id', v_id, 'allocations', v_alloc, 'not_given_back', v_left);
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 6. What is counted (REQ-BIL-14/15/16)
-- ---------------------------------------------------------------------------------------------------------------
-- calls: rounded up to the next full minute; under 15 seconds or marked as spam: not counted. The total follows the
-- ledger (the original entry and its adjustments), so a later, different duration subtracts or gives back the difference.
create or replace function public.zella_billing_charge_call(p_call_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c public.calls; v_secs integer; v_target numeric; v_done numeric; v_n integer; v_key text; s jsonb := public.zella_billing_settings(); v_at timestamptz;
begin
  -- the call row is locked, so two changes to one call are charged one after the other
  select * into c from public.calls where id = p_call_id for update;
  if c.id is null then return jsonb_build_object('result', 'not_found'); end if;
  select sum(u.duration_seconds), min(u.occurred_at) into v_secs, v_at from public.usage_records u
   where u.usage_type = 'ai_call' and u.call_id = c.id and u.status = 'recorded' and u.entry_kind in ('usage', 'adjustment');
  if v_secs is null then return jsonb_build_object('result', 'not_in_ledger'); end if;
  -- our failures are never billable (REQ-BIL-02): a call the call-status producer marked failed counts 0
  v_target := case when c.status = 'failed' or c.outcome = 'spam' or lower(coalesce(c.metadata ->> 'spam', c.metadata ->> 'is_spam', '')) in ('true', 'yes')
                     or v_secs < (s ->> 'min_call_seconds')::int then 0
                   else ceil(v_secs / 60.0) end;
  select coalesce(sum(quantity), 0), count(*) into v_done, v_n from public.usage_charges where source_kind = 'call' and source_id = c.id;
  -- numbered per call: the same state retried gives the same key; a later change gets the next number
  v_key := 'call:' || c.id || ':' || (v_n + 1) || ':' || v_done || '>' || v_target;
  if v_target > v_done then
    return public.zella_usage_consume(c.business_id, 'minutes', v_target - v_done, v_key, 'call', c.id, null, v_at);
  elsif v_target < v_done then
    return public.zella_usage_release(c.business_id, 'minutes', v_done - v_target, v_key, 'call', c.id);
  end if;
  return jsonb_build_object('result', 'unchanged');
end $$;

-- texts: by message part, as carriers count them. GSM-7 text (the GSM basic set, which includes é, è, ü, ñ and others;
-- ^ { } \ [ ] ~ | € take two places) fits 160 in one part and 153 per part when longer. Anything outside GSM-7
-- (most other accented or non-Latin letters, emoji) is sent as UCS-2: 70 in one part, 67 per part when longer,
-- with characters outside the basic plane (most emoji) taking two places.
create or replace function public.zella_sms_parts(p_body text) returns integer
language plpgsql immutable set search_path = public as $$
declare basic constant text := E'@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !"#¤%&''()*+,-./0123456789:;<=>?¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà';
        ext constant text := E'^{}\\[~]|€\f';
        ch text; septets integer := 0; units integer := 0; gsm boolean := true;
begin
  if coalesce(p_body, '') = '' then return 1; end if;
  foreach ch in array regexp_split_to_array(p_body, '') loop
    units := units + case when ascii(ch) > 65535 then 2 else 1 end;
    if gsm then
      if strpos(basic, ch) > 0 then septets := septets + 1;
      elsif strpos(ext, ch) > 0 then septets := septets + 2;
      else gsm := false; end if;
    end if;
  end loop;
  if gsm then return case when septets <= 160 then 1 else ceil(septets / 153.0)::int end; end if;
  return case when units <= 70 then 1 else ceil(units / 67.0)::int end;
end $$;

-- which outbound messages count against the business's allowance: messages to customers. Alerts Zella Voice sends to
-- the business's own owners and staff (staff alerts, owner notifications) are not counted. Appointment confirmations
-- and reminders are 'appointment' (they may use the buffer); everything else is 'routine'.
create or replace function public.zella_billing_message_kind(p_meta jsonb) returns text
language sql immutable set search_path = public as $$
  select case when coalesce(p_meta ->> 'staff_alert', '') = 'true' or coalesce(p_meta ->> 'dedupe_key', '') like 'notif:%'
                   or coalesce(p_meta ->> 'dedupe_key', '') like 'staffsms:%' then null
              when coalesce(p_meta ->> 'dedupe_key', '') like 'reminder:%' then 'appointment'
              else 'routine' end;
$$;

create or replace function public.zella_billing_message_trg() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_kind text; v_res text := case when tg_table_name = 'sms_messages' then 'texts' else 'emails' end; r jsonb;
begin
  if new.direction is distinct from 'outbound' or new.business_id is null or new.status not in ('sent', 'delivered') then return null; end if;
  if tg_op = 'UPDATE' and old.status in ('sent', 'delivered') then return null; end if;
  v_kind := public.zella_billing_message_kind(new.metadata);
  if v_kind is null then return null; end if;
  begin
    if v_res = 'texts' then
      r := public.zella_usage_consume(new.business_id, 'texts', public.zella_sms_parts(to_jsonb(new) ->> 'message_body'), 'sms:' || new.id, 'sms',
                                      new.id, v_kind, coalesce(new.sent_at, now()));
    else
      r := public.zella_usage_consume(new.business_id, 'emails', 1, 'email:' || new.id, 'email', new.id, v_kind, coalesce(new.sent_at, now()));
    end if;
    if r ->> 'result' = 'recorded' then perform public.zella_billing_evaluate_alerts(new.business_id, v_res); end if;
  exception when others then
    -- a message is never blocked by counting; the failure is listed and retried by reconciliation
    perform public.zella_usage_open_issue(new.business_id, null, 'billing_charge_failed', sqlerrm,
                                          jsonb_build_object('table', tg_table_name, 'id', new.id));
  end;
  return null;
end $$;
drop trigger if exists zella_billing_sms_trg on public.sms_messages;
create trigger zella_billing_sms_trg after insert or update of status on public.sms_messages for each row execute function public.zella_billing_message_trg();
drop trigger if exists zella_billing_email_trg on public.email_messages;
create trigger zella_billing_email_trg after insert or update of status on public.email_messages for each row execute function public.zella_billing_message_trg();

-- calls: every new ledger entry, and a call later marked as spam or failed
create or replace function public.zella_billing_call_trg() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_call uuid; v_biz uuid; r jsonb;
begin
  if tg_table_name = 'usage_records' then
    if new.usage_type <> 'ai_call' or new.call_id is null then return null; end if;
    v_call := new.call_id; v_biz := new.business_id;
  else
    if new.outcome is not distinct from old.outcome and new.status is not distinct from old.status and new.metadata is not distinct from old.metadata then return null; end if;
    if not exists (select 1 from public.usage_charges where source_kind = 'call' and source_id = new.id) then return null; end if;
    v_call := new.id; v_biz := new.business_id;
  end if;
  begin
    r := public.zella_billing_charge_call(v_call);
  exception when others then
    perform public.zella_usage_open_issue(v_biz, v_call, 'billing_charge_failed', sqlerrm, jsonb_build_object('table', tg_table_name));
  end;
  return null;
end $$;
drop trigger if exists zella_billing_usage_trg on public.usage_records;
create trigger zella_billing_usage_trg after insert on public.usage_records for each row execute function public.zella_billing_call_trg();
drop trigger if exists zella_billing_call_spam_trg on public.calls;
create trigger zella_billing_call_spam_trg after update of outcome, status, metadata on public.calls for each row execute function public.zella_billing_call_trg();

-- retries what could not be counted (called by the hourly usage check; also by a billing admin). A call is retried by
-- its id; for messages one open issue per business stands for every message of the last 60 days not counted yet. An
-- issue is resolved only when every charge came back recorded (or already recorded, or outside any period); anything
-- else keeps it open for the next try.
create or replace function public.zella_billing_retry_charges(p_limit integer default 100) returns integer
language plpgsql security definer set search_path = public as $$
declare i record; n integer := 0; m record; r jsonb; v_kind text;
begin
  for i in select * from public.usage_processing_issues where kind = 'billing_charge_failed' and status <> 'resolved' and next_attempt_at <= now()
            order by next_attempt_at limit greatest(1, least(coalesce(p_limit, 100), 500)) for update skip locked loop
    begin
      if i.call_id is not null then
        r := public.zella_billing_charge_call(i.call_id);
        if coalesce(r ->> 'result', '') not in ('recorded', 'duplicate', 'released', 'unchanged', 'not_configured', 'nothing_charged', 'not_found', 'not_in_ledger') then
          raise exception 'NOT_COUNTED: %', coalesce(r ->> 'result', 'no answer');
        end if;
        perform public.zella_evaluate_call_usage_thresholds(i.business_id);
      else
        for m in select 'texts' as res, x.id, x.business_id, public.zella_sms_parts(x.message_body) as qty, x.metadata, x.sent_at from public.sms_messages x
                  where x.business_id = i.business_id and x.direction = 'outbound' and x.status in ('sent', 'delivered') and x.created_at > now() - interval '60 days'
                    and not exists (select 1 from public.usage_charges u where u.idempotency_key = 'sms:' || x.id)
                 union all
                 select 'emails', x.id, x.business_id, 1, x.metadata, x.sent_at from public.email_messages x
                  where x.business_id = i.business_id and x.direction = 'outbound' and x.status in ('sent', 'delivered') and x.created_at > now() - interval '60 days'
                    and not exists (select 1 from public.usage_charges u where u.idempotency_key = 'email:' || x.id) loop
          v_kind := public.zella_billing_message_kind(m.metadata);
          continue when v_kind is null;
          r := public.zella_usage_consume(m.business_id, m.res, m.qty, case when m.res = 'texts' then 'sms:' else 'email:' end || m.id,
                                          case when m.res = 'texts' then 'sms' else 'email' end, m.id, v_kind, coalesce(m.sent_at, now()));
          if coalesce(r ->> 'result', '') not in ('recorded', 'duplicate', 'not_configured') then
            raise exception 'NOT_COUNTED: % %', m.res, coalesce(r ->> 'result', 'no answer');
          end if;
        end loop;
        perform public.zella_billing_evaluate_alerts(i.business_id, 'texts');
        perform public.zella_billing_evaluate_alerts(i.business_id, 'emails');
      end if;
      update public.usage_processing_issues set status = 'resolved', resolved_at = now(), resolution = 'recorded', updated_at = now() where id = i.id;
      n := n + 1;
    exception when others then
      update public.usage_processing_issues set attempts = attempts + 1, last_error = left(sqlerrm, 300),
             next_attempt_at = now() + make_interval(mins => least(240, 15 * power(2, least(attempts, 4))::int)), updated_at = now() where id = i.id;
    end;
  end loop;
  return n;
end $$;

-- the hourly check opens each subscribed business's current period, so a quiet month still exists for the next
-- month's rollover (a monthly period is only known while it is the subscription's current one)
create or replace function public.zella_billing_open_current_periods(p_limit integer default 1000) returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0;
begin
  for r in select distinct s.business_id from public.subscriptions s join public.business_plans bp on bp.business_id = s.business_id
            where s.status in ('trial', 'active', 'renewal_due', 'past_due', 'grace_period')
              and not exists (select 1 from public.billing_periods p where p.business_id = s.business_id and p.period_start <= now() and now() < p.period_end)
            limit greatest(1, least(coalesce(p_limit, 1000), 10000)) loop
    begin
      if (public.zella_billing_open_period(r.business_id, now())).id is not null then n := n + 1; end if;
    exception when others then null;   -- one business never stops the others; it is tried again next hour
    end;
  end loop;
  return n;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 7. Balances, checks and alerts
-- ---------------------------------------------------------------------------------------------------------------
-- one resource in the current period (read-only: a period not opened yet shows the plan's values)
create or replace function public.zella_billing_balance(p_business_id uuid, p_resource text, p_at timestamptz default now()) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare bnd jsonb; p public.billing_periods; b public.business_plans; s jsonb := public.zella_billing_settings(); v_inc numeric; v_used numeric;
        v_buf numeric; v_buf_used numeric; v_over numeric;
begin
  bnd := public.zella_billing_period_bounds(p_business_id, p_at);
  if bnd is null then return jsonb_build_object('configured', false, 'reason', 'no_current_period'); end if;
  select * into p from public.billing_periods where business_id = p_business_id and period_start = (bnd ->> 'from')::timestamptz;
  if p.id is null then
    b := public.zella_billing_plan_at(p_business_id, (bnd ->> 'from')::timestamptz);
    if b.id is null then return jsonb_build_object('configured', false, 'reason', 'no_plan'); end if;
    v_inc := case when (bnd ->> 'trial')::boolean then (s ->> ('trial_' || p_resource))::numeric
                  else case p_resource when 'minutes' then b.minutes when 'texts' then b.texts else b.emails end end;
    v_used := 0; v_over := 0;
    v_buf := case when (bnd ->> 'trial')::boolean or p_resource = 'minutes' then 0 else floor(v_inc * (s ->> 'buffer_percent')::numeric / 100) end;
    v_buf_used := 0;
  else
    select coalesce(sum(granted) filter (where kind <> 'buffer'), 0), coalesce(sum(used) filter (where kind <> 'buffer'), 0),
           coalesce(sum(granted) filter (where kind = 'buffer'), 0), coalesce(sum(used) filter (where kind = 'buffer'), 0)
      into v_inc, v_used, v_buf, v_buf_used from public.allowance_buckets where period_id = p.id and resource = p_resource;
    select coalesce(sum(over_quantity), 0) into v_over from public.usage_charges where period_id = p.id and resource = p_resource;
  end if;
  return jsonb_build_object('configured', true, 'resource', p_resource, 'period_from', bnd ->> 'from', 'period_to', bnd ->> 'to',
    'trial', (bnd ->> 'trial')::boolean, 'included', trim_scale(v_inc), 'used', trim_scale(v_used + v_buf_used + v_over),
    'remaining', trim_scale(greatest(v_inc - v_used, 0)), 'buffer', trim_scale(v_buf), 'buffer_remaining', trim_scale(greatest(v_buf - v_buf_used, 0)),
    'over', trim_scale(v_over),
    'percent_used', case when v_inc > 0 then round((v_used + v_buf_used + v_over) * 100 / v_inc, 1) end,
    'exhausted', v_inc - v_used <= 0, 'buffer_exhausted', v_inc - v_used <= 0 and v_buf - v_buf_used <= 0);
end $$;

-- texts and emails at 100% (D-43): routine messages stop; appointment confirmations and reminders use the buffer
-- until 105%. Reported here for the message claims; nothing calls it yet (stopping messages is a live change).
create or replace function public.zella_message_allowance(p_business_id uuid, p_channel text, p_kind text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare a jsonb;
begin
  if p_channel not in ('sms', 'email') or p_kind not in ('appointment', 'routine') then raise exception 'BAD_INPUT'; end if;
  a := public.zella_billing_balance(p_business_id, case p_channel when 'sms' then 'texts' else 'emails' end);
  if not (a ->> 'configured')::boolean then return jsonb_build_object('would_permit', null, 'enforced', false, 'reason', a ->> 'reason'); end if;
  return jsonb_build_object('enforced', false, 'remaining', a -> 'remaining', 'buffer_remaining', a -> 'buffer_remaining',
    'would_permit', not (a ->> 'exhausted')::boolean or (p_kind = 'appointment' and not (a ->> 'buffer_exhausted')::boolean),
    'reason', case when not (a ->> 'exhausted')::boolean then 'within_allowance'
                   when p_kind = 'appointment' and not (a ->> 'buffer_exhausted')::boolean then 'buffer'
                   else 'allowance_used' end);
end $$;

-- alerts at 80% and 100% for texts and emails, once per business, resource, level and period (minutes use the
-- existing minute alerts, which now read the same balances)
create or replace function public.zella_billing_evaluate_alerts(p_business_id uuid, p_resource text) returns integer
language plpgsql security definer set search_path = public as $$
declare a jsonb; t integer; v_ev uuid; v_label text := case p_resource when 'texts' then 'texts' else 'emails' end; v_note uuid;
begin
  if p_resource not in ('texts', 'emails') then return 0; end if;
  a := public.zella_billing_balance(p_business_id, p_resource);
  if not (a ->> 'configured')::boolean or coalesce((a ->> 'included')::numeric, 0) <= 0 then return 0; end if;
  for t in select x::int from jsonb_array_elements_text(public.zella_billing_settings() -> 'alert_percents') x order by 1 desc loop
    continue when (a ->> 'percent_used')::numeric < t;
    insert into public.usage_threshold_events (business_id, threshold_key, period_key, event_type, usage_minutes, limit_minutes, resource)
    values (p_business_id, p_resource || ':pct:' || t, a ->> 'period_from', case when t >= 100 then 'allowance_limit' else 'approaching' end,
            (a ->> 'used')::numeric, (a ->> 'included')::numeric, p_resource)
    on conflict do nothing returning id into v_ev;
    exit when v_ev is null;   -- this level (and so the lower ones) was already notified
    perform public.zella_notify_owners(p_business_id, 'usage_threshold',
      case when t >= 100 then 'Your included ' || v_label || ' are used up' else 'You have used ' || t || '% of your ' || v_label end,
      round((a ->> 'used')::numeric) || ' of ' || round((a ->> 'included')::numeric) || ' ' || v_label || ' this period.'
        || case when t >= 100 then ' Appointment confirmations and reminders have a small extra allowance (5%). Ask Zella Voice support to add a pack.' else '' end,
      case when t >= 100 then 'urgent' else 'warning' end, 'settings');
    select id into v_note from public.staff_notifications where business_id = p_business_id and kind = 'usage_threshold' order by created_at desc limit 1;
    update public.usage_threshold_events set notification_id = v_note where id = v_ev;
    return 1;
  end loop;
  return 0;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 8. Packs, auto-reload, overview
-- ---------------------------------------------------------------------------------------------------------------
-- a free pack from a billing admin (an adjustment, REQ-BIL-10): reason, audit, once per key; it joins the current period
create or replace function public.zella_admin_pack_grant(p_business_id uuid, p_pack_code text, p_reason text, p_idempotency_key text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c public.billing_pack_catalog; p public.billing_periods; v public.pack_purchases;
begin
  if auth.uid() is null or not public.zella_admin_can('billing.manage') then raise exception 'NOT_ALLOWED'; end if;
  if p_reason is null or length(trim(p_reason)) < 5 then raise exception 'REASON_REQUIRED'; end if;
  if p_idempotency_key is null or length(p_idempotency_key) not between 8 and 100 then raise exception 'BAD_IDEMPOTENCY_KEY'; end if;
  select * into c from public.billing_pack_catalog where code = p_pack_code and active;
  if c.code is null then raise exception 'UNKNOWN_PACK'; end if;
  p := public.zella_billing_open_period(p_business_id, now());
  if p.id is null then raise exception 'NO_CURRENT_PERIOD'; end if;
  select * into v from public.pack_purchases where business_id = p_business_id and idempotency_key = p_idempotency_key;
  if v.id is not null then
    if v.pack_code <> p_pack_code then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
    return jsonb_build_object('result', 'duplicate', 'pack_purchase_id', v.id);
  end if;
  insert into public.pack_purchases (business_id, pack_code, resource, quantity, price_cents, status, source, reason, period_id, idempotency_key, created_by)
  values (p_business_id, c.code, c.resource, c.quantity, c.price_cents, 'granted', 'admin_grant', left(trim(p_reason), 500), p.id, p_idempotency_key, auth.uid())
  returning * into v;
  insert into public.allowance_buckets (business_id, period_id, resource, kind, pack_purchase_id, granted, expires_at)
  values (p_business_id, p.id, c.resource, 'pack', v.id, c.quantity, p.period_end);
  insert into public.audit_logs (business_id, user_id, action, entity_type, entity_id, new_data)
  values (p_business_id, auth.uid(), 'billing.pack_granted', 'pack_purchase', v.id,
          jsonb_build_object('pack', c.code, 'quantity', c.quantity, 'list_price_cents', c.price_cents, 'charged', false, 'reason', v.reason, 'expires_at', p.period_end));
  return jsonb_build_object('result', 'granted', 'pack_purchase_id', v.id, 'expires_at', p.period_end);
end $$;

-- owner only (REQ-BIL-23); stored for now: automatic reloads need payments (step 4)
create or replace function public.zella_auto_reload_save(p_business_id uuid, p_resource text, p_enabled boolean, p_threshold integer,
    p_pack_code text, p_monthly_cap_cents bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c public.billing_pack_catalog; old jsonb;
begin
  if auth.uid() is null or not public.zella_has_role(p_business_id, array['owner']) then raise exception 'NOT_ALLOWED'; end if;
  select * into c from public.billing_pack_catalog where code = p_pack_code and active;
  if c.code is null or c.resource <> p_resource then raise exception 'BAD_INPUT' using detail = 'pack'; end if;
  if p_enabled is null or p_threshold is null or p_threshold < 0 or p_threshold > 1000000 then raise exception 'BAD_INPUT' using detail = 'threshold'; end if;
  if p_monthly_cap_cents is null or p_monthly_cap_cents < c.price_cents or p_monthly_cap_cents > 10000000 then
    raise exception 'BAD_INPUT' using detail = 'monthly_cap';   -- the cap must allow at least one pack
  end if;
  select to_jsonb(a) into old from public.auto_reload_settings a where business_id = p_business_id and resource = p_resource;
  insert into public.auto_reload_settings (business_id, resource, enabled, threshold, pack_code, monthly_cap_cents, updated_by, updated_at)
  values (p_business_id, p_resource, p_enabled, p_threshold, p_pack_code, p_monthly_cap_cents, auth.uid(), now())
  on conflict (business_id, resource) do update set enabled = excluded.enabled, threshold = excluded.threshold, pack_code = excluded.pack_code,
    monthly_cap_cents = excluded.monthly_cap_cents, updated_by = excluded.updated_by, updated_at = now();
  insert into public.audit_logs (business_id, user_id, action, entity_type, entity_id, old_data, new_data)
  values (p_business_id, auth.uid(), 'billing.auto_reload_updated', 'business', p_business_id, old,
          jsonb_build_object('resource', p_resource, 'enabled', p_enabled, 'threshold', p_threshold, 'pack', p_pack_code, 'monthly_cap_cents', p_monthly_cap_cents));
  return jsonb_build_object('result', 'saved', 'active', false, 'note', 'Automatic reloads start once payments are switched on.');
end $$;

-- the Billing & Subscription page and the admin view (REQ-BIL-05): the business owner, or a billing admin
create or replace function public.zella_billing_overview(p_business_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare b public.business_plans; p public.billing_periods; s public.subscriptions;
begin
  if auth.uid() is null or not (public.zella_has_role(p_business_id, array['owner']) or public.zella_admin_can('billing.view')) then
    raise exception 'NOT_ALLOWED';
  end if;
  b := public.zella_billing_plan_current(p_business_id);
  s := public.zella_current_subscription(p_business_id);
  p := public.zella_billing_open_period(p_business_id, now());
  return jsonb_build_object(
    'plan', case when b.id is not null then jsonb_build_object('version', b.version, 'tier', b.tier, 'billing_interval', b.billing_interval,
      'price_cents', b.price_cents, 'setup_fee_cents', b.setup_fee_cents, 'currency', b.currency, 'minutes', b.minutes, 'texts', b.texts,
      'emails', b.emails, 'team_seats', b.team_seats, 'phone_numbers', b.phone_numbers, 'locations', b.locations, 'languages', to_jsonb(b.languages),
      'trial_enabled', b.trial_enabled, 'overage_cents_per_minute', b.overage_cents_per_minute) end,
    'subscription', case when s.id is not null then jsonb_build_object('status', s.status, 'trial_end_at', s.trial_end_at,
      'current_period_start', s.current_period_start, 'current_period_end', s.current_period_end) end,
    'period', case when p.id is not null then jsonb_build_object('from', p.period_start, 'to', p.period_end, 'trial', p.is_trial,
      'days_left', greatest(0, ceil(extract(epoch from p.period_end - now()) / 86400))::int) end,
    'usage', jsonb_build_object('minutes', public.zella_billing_balance(p_business_id, 'minutes'), 'texts', public.zella_billing_balance(p_business_id, 'texts'),
      'emails', public.zella_billing_balance(p_business_id, 'emails')),
    'balances', coalesce((select jsonb_agg(jsonb_build_object('resource', k.resource, 'kind', k.kind, 'granted', k.granted, 'used', k.used,
        'remaining', k.granted - k.used, 'expires_at', k.expires_at, 'pack', pp.pack_code)
        order by k.resource, public.zella_billing_bucket_rank(k.kind, k.pack_purchase_id is not null), pp.purchased_at nulls first)
      from public.allowance_buckets k left join public.pack_purchases pp on pp.id = k.pack_purchase_id where k.period_id = p.id), '[]'::jsonb),
    'auto_reload', coalesce((select jsonb_agg(jsonb_build_object('resource', a.resource, 'enabled', a.enabled, 'threshold', a.threshold,
        'pack', a.pack_code, 'monthly_cap_cents', a.monthly_cap_cents) order by a.resource) from public.auto_reload_settings a where a.business_id = p_business_id), '[]'::jsonb),
    'packs', coalesce((select jsonb_agg(jsonb_build_object('code', c.code, 'resource', c.resource, 'quantity', c.quantity, 'price_cents', c.price_cents,
        'rollover_if_unused', case when c.resource = 'minutes' then floor(c.quantity * (public.zella_billing_settings() ->> 'rollover_percent')::numeric / 100) else 0 end)
        order by c.resource, c.quantity) from public.billing_pack_catalog c where c.active), '[]'::jsonb));
end $$;

-- whether a plan is saved, without any price or allowance: for the setup wizard's Review row and Finish button, which
-- admins without billing permission also use (the server checks it again when setup is finished)
create or replace function public.zella_setup_plan_saved(p_business_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v integer;
begin
  if auth.uid() is null or not (public.zella_admin_can('businesses.manage') or public.zella_admin_can('billing.view')) then raise exception 'NOT_ALLOWED'; end if;
  select max(version) into v from public.business_plans where business_id = p_business_id;
  return jsonb_build_object('saved', v is not null, 'version', v);
end $$;

-- the plan page in Create Business (billing admins): the saved plan, its versions, and whether this admin may change it
create or replace function public.zella_admin_plan_get(p_business_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare b public.business_plans;
begin
  if auth.uid() is null or not public.zella_admin_can('billing.view') then raise exception 'NOT_ALLOWED'; end if;
  b := public.zella_billing_plan_current(p_business_id);
  return jsonb_build_object('can_edit', public.zella_admin_can('billing.manage'),
    'settings', public.zella_billing_settings() - 'unit_costs',
    'plan', case when b.id is not null then jsonb_build_object('version', b.version, 'tier', b.tier, 'billing_interval', b.billing_interval,
      'price_cents', b.price_cents, 'setup_fee_cents', b.setup_fee_cents, 'minutes', b.minutes, 'texts', b.texts, 'emails', b.emails,
      'team_seats', b.team_seats, 'phone_numbers', b.phone_numbers, 'locations', b.locations, 'languages', to_jsonb(b.languages),
      'trial_enabled', b.trial_enabled, 'overage_cents_per_minute', b.overage_cents_per_minute, 'estimate', b.estimate, 'acknowledged_warnings', b.acknowledged_warnings, 'saved_at', b.created_at) end,
    'versions', coalesce((select jsonb_agg(jsonb_build_object('version', v.version, 'tier', v.tier, 'price_cents', v.price_cents,
        'billing_interval', v.billing_interval, 'saved_at', v.created_at) order by v.version desc)
      from public.business_plans v where v.business_id = p_business_id), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- 9. Existing logic: patches (each checks the function is the version it was written against)
-- ---------------------------------------------------------------------------------------------------------------
alter table public.subscriptions alter column plan_id drop not null;
alter table public.business_usage_preferences alter column notify_thresholds set default '{80,100}'::integer[];
update public.business_usage_preferences set notify_thresholds = '{80,100}' where notify_thresholds is distinct from '{80,100}';

do $$
declare def text;
begin
  def := pg_get_functiondef('public.zella_entitlement_allows(uuid, text, numeric)'::regprocedure);
  if position('zella_billing_allowances' in def) = 0 then
    def := replace(def, $a$  select nullif(p.limits ->> p_key, '')::numeric into v_limit from public.plans p where p.id = s.plan_id;$a$,
                        $a$  v_limit := nullif(public.zella_plan_limits(p_business_id) ->> p_key, '')::numeric;   /* zella_billing_allowances */$a$);
    if position('zella_billing_allowances' in def) = 0 then raise exception 'zella_entitlement_allows has changed; review this patch'; end if;
    execute def;
  end if;

  def := pg_get_functiondef('public.zella_language_allowance(uuid)'::regprocedure);
  if position('zella_billing_allowances' in def) = 0 then
    def := replace(def, $a$  select p.limits ->> 'languages' into v from public.plans p where p.id = s.plan_id;$a$,
                        $a$  v := public.zella_plan_limits(p_business_id) ->> 'languages';   /* zella_billing_allowances */$a$);
    if position('zella_billing_allowances' in def) = 0 then raise exception 'zella_language_allowance has changed; review this patch'; end if;
    execute def;
  end if;

  def := pg_get_functiondef('public.zella_entitlements(uuid)'::regprocedure);
  if position('zella_billing_allowances' in def) = 0 then
    def := replace(def, $a$  select jsonb_build_object('plan', p.slug, 'status', s.status, 'features', coalesce(p.features, '{}'::jsonb), 'limits', coalesce(p.limits, '{}'::jsonb),$a$,
                        $a$  select jsonb_build_object('plan', coalesce(p.slug, 'custom'), 'status', s.status, 'features', coalesce(p.features, '{}'::jsonb), 'limits', public.zella_plan_limits(p_business_id),   /* zella_billing_allowances */$a$);
    def := replace(def, $a$    into r from public.subscriptions s join public.plans p on p.id = s.plan_id$a$,
                        $a$    into r from public.subscriptions s left join public.plans p on p.id = s.plan_id$a$);
    if position('zella_billing_allowances' in def) = 0 or position('left join public.plans p on p.id = s.plan_id' in def) = 0 then
      raise exception 'zella_entitlements has changed; review this patch';
    end if;
    execute def;
  end if;

  -- minutes: the business's balances (plan + rollover + packs) when it has its own plan
  def := pg_get_functiondef('public.zella_call_allowance(uuid)'::regprocedure);
  if position('zella_billing_allowances' in def) = 0 then
    def := replace(def, $a$  if s.id is null then return jsonb_build_object('configured', false, 'reason', 'no_active_subscription'); end if;$a$,
                        $a$  if s.id is null then return jsonb_build_object('configured', false, 'reason', 'no_active_subscription'); end if;
  if (public.zella_billing_plan_current(p_business_id)).id is not null then   /* zella_billing_allowances */
    v_raw := public.zella_billing_balance(p_business_id, 'minutes')::text;
    if not (v_raw::jsonb ->> 'configured')::boolean then return jsonb_build_object('configured', false, 'reason', v_raw::jsonb ->> 'reason', 'subscription_id', s.id); end if;
    return jsonb_build_object('configured', true, 'subscription_id', s.id, 'subscription_status', s.status, 'period_from', v_raw::jsonb ->> 'period_from',
      'period_to', v_raw::jsonb ->> 'period_to', 'included_minutes', (v_raw::jsonb ->> 'included')::numeric, 'consumed_minutes', (v_raw::jsonb ->> 'used')::numeric,
      'remaining_minutes', (v_raw::jsonb ->> 'remaining')::numeric, 'percent_used', (v_raw::jsonb ->> 'percent_used')::numeric,
      'exhausted', (v_raw::jsonb ->> 'exhausted')::boolean);
  end if;$a$);
    if position('zella_billing_allowances' in def) = 0 then raise exception 'zella_call_allowance has changed; review this patch'; end if;
    execute def;
  end if;

  -- alerts at 80% and 100% (owner, 13 Nov 2026)
  def := pg_get_functiondef('public.zella_evaluate_call_usage_thresholds(uuid)'::regprocedure);
  if position('zella_billing_allowances' in def) = 0 then
    def := replace(def, $a$  select coalesce(u.notify_thresholds, '{70,90,100}') into v_legacy from public.business_usage_preferences u where u.business_id = p_business_id;
  v_legacy := coalesce(v_legacy, '{70,90,100}');$a$,
                        $a$  v_legacy := array(select x::int from jsonb_array_elements_text(public.zella_billing_settings() -> 'alert_percents') x);   /* zella_billing_allowances */$a$);
    if position('zella_billing_allowances' in def) = 0 then raise exception 'zella_evaluate_call_usage_thresholds has changed; review this patch'; end if;
    execute def;
  end if;

  def := pg_get_functiondef('public.zella_save_usage_preferences(uuid, integer[], text, bigint, text)'::regprocedure);
  if position('zella_billing_allowances' in def) = 0 then
    def := replace(def, $a$  values (p_business_id, coalesce(p_thresholds, '{70,90,100}'), p_mode,$a$,
                        $a$  values (p_business_id, '{80,100}'::integer[] /* zella_billing_allowances: alerts are always at 80% and 100% */, p_mode,$a$);
    def := replace(def, $a$  if p_mode <> 'stop' and (p_spend_limit_cents is null or p_spend_limit_cents <= 0) then raise exception 'SPEND_LIMIT_REQUIRED'; end if;$a$,
                        $a$  if p_mode <> 'stop' and (p_spend_limit_cents is null or p_spend_limit_cents <= 0) then raise exception 'SPEND_LIMIT_REQUIRED'; end if;
  -- D-44: pay as you go only on a plan with a per-minute rate (zella_billing_allowances)
  if p_mode = 'pay_as_you_go' and (public.zella_billing_plan_current(p_business_id)).id is not null
     and (public.zella_billing_plan_current(p_business_id)).overage_cents_per_minute is null then raise exception 'PLAN_NO_PAY_AS_YOU_GO'; end if;$a$);
    if position('zella_billing_allowances' in def) = 0 or position('PLAN_NO_PAY_AS_YOU_GO' in def) = 0 then raise exception 'zella_save_usage_preferences has changed; review this patch'; end if;
    execute def;
  end if;

  def := pg_get_functiondef('public.zella_usage_preferences(uuid)'::regprocedure);
  if position('zella_billing_allowances' in def) = 0 then
    def := replace(def, $a$'notify_thresholds', coalesce(r.notify_thresholds, '{70,90,100}'),$a$,
                        $a$'notify_thresholds', '{80,100}'::integer[] /* zella_billing_allowances */,$a$);
    if position('zella_billing_allowances' in def) = 0 then raise exception 'zella_usage_preferences has changed; review this patch'; end if;
    execute def;
  end if;

  -- reconciliation also retries what could not be counted
  def := pg_get_functiondef('public.zella_check_usage_thresholds()'::regprocedure);
  if position('zella_billing_allowances' in def) = 0 then
    def := replace(def, $a$    begin n := n + public.zella_evaluate_call_usage_thresholds(r.id); exception when others then null; end;
  end loop;$a$,
                        $a$    begin n := n + public.zella_evaluate_call_usage_thresholds(r.id); exception when others then null; end;
  end loop;
  begin perform public.zella_billing_open_current_periods(); perform public.zella_billing_retry_charges(200); exception when others then null; end;   /* zella_billing_allowances */$a$);
    if position('zella_billing_allowances' in def) = 0 then raise exception 'zella_check_usage_thresholds has changed; review this patch'; end if;
    execute def;
  end if;
end $$;

-- the shared plans table: billing admins, and members of a business on that plan (per-business prices are never in it)
drop policy if exists "Anyone can view active plans" on public.plans;
drop policy if exists "zella_plans_read" on public.plans;
create policy "zella_plans_read" on public.plans as permissive for select to authenticated
  using (public.zella_admin_can('billing.view')
         or exists (select 1 from public.subscriptions s where s.plan_id = plans.id and public.zella_is_member(s.business_id)));
revoke select on public.plans from anon;

-- ---------------------------------------------------------------------------------------------------------------
-- 10. Who may call what
-- ---------------------------------------------------------------------------------------------------------------
revoke all on function public.zella_billing_settings(), public.zella_plan_evaluate(jsonb), public.zella_billing_plan_current(uuid),
  public.zella_billing_plan_at(uuid, timestamptz), public.zella_plan_limits(uuid), public.zella_billing_period_bounds(uuid, timestamptz),
  public.zella_billing_open_period(uuid, timestamptz), public.zella_usage_consume(uuid, text, numeric, text, text, uuid, text, timestamptz),
  public.zella_usage_release(uuid, text, numeric, text, text, uuid), public.zella_billing_charge_call(uuid), public.zella_billing_retry_charges(integer),
  public.zella_billing_rollover_reconcile(uuid), public.zella_billing_open_current_periods(integer),
  public.zella_billing_balance(uuid, text, timestamptz), public.zella_message_allowance(uuid, text, text), public.zella_billing_evaluate_alerts(uuid, text),
  public.zella_billing_message_trg(), public.zella_billing_call_trg(), public.zella_billing_immutable_trg(),
  public.zella_admin_plan_save(uuid, jsonb, jsonb, text), public.zella_admin_pack_grant(uuid, text, text, text),
  public.zella_auto_reload_save(uuid, text, boolean, integer, text, bigint), public.zella_billing_overview(uuid), public.zella_admin_plan_get(uuid), public.zella_setup_plan_saved(uuid)
  from public, anon, authenticated;
grant execute on function public.zella_billing_settings(), public.zella_plan_evaluate(jsonb), public.zella_billing_plan_current(uuid),
  public.zella_billing_plan_at(uuid, timestamptz), public.zella_plan_limits(uuid), public.zella_billing_period_bounds(uuid, timestamptz),
  public.zella_billing_open_period(uuid, timestamptz), public.zella_usage_consume(uuid, text, numeric, text, text, uuid, text, timestamptz),
  public.zella_usage_release(uuid, text, numeric, text, text, uuid), public.zella_billing_charge_call(uuid), public.zella_billing_retry_charges(integer),
  public.zella_billing_rollover_reconcile(uuid), public.zella_billing_open_current_periods(integer),
  public.zella_billing_balance(uuid, text, timestamptz), public.zella_message_allowance(uuid, text, text), public.zella_billing_evaluate_alerts(uuid, text),
  public.zella_admin_plan_save(uuid, jsonb, jsonb, text), public.zella_admin_pack_grant(uuid, text, text, text),
  public.zella_auto_reload_save(uuid, text, boolean, integer, text, bigint), public.zella_billing_overview(uuid), public.zella_admin_plan_get(uuid), public.zella_setup_plan_saved(uuid)
  to service_role;
-- signed in: the admin and owner functions check the caller themselves (the plan check: billing admins only)
grant execute on function public.zella_plan_evaluate(jsonb), public.zella_admin_plan_save(uuid, jsonb, jsonb, text),
  public.zella_admin_pack_grant(uuid, text, text, text), public.zella_auto_reload_save(uuid, text, boolean, integer, text, bigint),
  public.zella_billing_overview(uuid), public.zella_admin_plan_get(uuid), public.zella_setup_plan_saved(uuid) to authenticated;
revoke all on function public.zella_sms_parts(text), public.zella_billing_message_kind(jsonb), public.zella_billing_bucket_rank(text, boolean) from public, anon;
grant execute on function public.zella_sms_parts(text), public.zella_billing_message_kind(jsonb), public.zella_billing_bucket_rank(text, boolean) to authenticated, service_role;

commit;
